  // spellchecker: ignore-next-line
  product shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_recently_viewed_products_shopping_mall_p_168f31d0")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_id], map: "shopping_mall_recently_viewed_products_shopping_mall_p_842ad1c5")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, viewed_at], map: "shopping_mall_recently_viewed_products_shopping_mall_c_97f0f9e1")
  @@index([session_id, viewed_at])
  @@index([viewed_at])
